<?php
namespace App\Services;
use App\Models\Fueling; use App\Models\FuelRequest; use App\Models\User; use App\Models\Vehicle; use Illuminate\Support\Facades\DB;
class FuelingService
{
 public function fulfill(User $actor,array $attributes): Fueling { $this->ensureSupervisor($actor); return DB::transaction(function() use($actor,$attributes){ $request=FuelRequest::query()->lockForUpdate()->findOrFail($attributes['request_id']); $vehicle=Vehicle::query()->lockForUpdate()->findOrFail($request->vehicle_id); if($request->status!=='approved') throw new OperationalStateException('Somente requisições aprovadas podem ser cumpridas.'); if($request->requiresAuthorization() && !$request->hasActiveAuthorization()) throw new OperationalStateException('A autorização desta requisição expirou. Solicite uma nova autorização antes de registrar o abastecimento.'); if(Fueling::query()->where('request_id',$request->id)->lockForUpdate()->exists()) throw new OperationalStateException('A requisição já possui abastecimento vinculado.'); if((int)$attributes['vehicle_id']!==$request->vehicle_id || (int)$attributes['fuel_type_id']!==$request->fuel_type_id) throw new OperationalStateException('Veículo ou combustível divergente da requisição aprovada.'); $odometer=(int)$attributes['odometer']; if($vehicle->status!=='active'||$odometer<(int)$vehicle->current_odometer) throw new OperationalStateException('Veículo inativo ou hodômetro regressivo.'); $liters=(float)$attributes['liters']; $unitPrice=(float)$attributes['unit_price']; if($liters<=0||$unitPrice<0) throw new OperationalStateException('Litros devem ser positivos e preço unitário não pode ser negativo.'); $fueling=Fueling::create(['fueling_at'=>$attributes['fueling_at']??now(),'request_id'=>$request->id,'vehicle_id'=>$request->vehicle_id,'driver_person_id'=>$attributes['driver_person_id']??$request->driver_person_id,'fuel_type_id'=>$request->fuel_type_id,'odometer'=>$odometer,'liters'=>$attributes['liters'],'unit_price'=>$attributes['unit_price'],'total_amount'=>number_format(round($liters*$unitPrice,2),2,'.',''),'invoice_number'=>$attributes['invoice_number']??null,'station_name'=>$attributes['station_name']??null,'notes'=>$attributes['notes']??null,'created_by_user_id'=>$actor->id]); if($odometer>(int)$vehicle->current_odometer) $vehicle->update(['current_odometer'=>$odometer]); $request->update(['status'=>'fulfilled']); return $fueling->fresh(); }); }
 private function ensureSupervisor(User $actor): void { if(!$actor->is_active||!$actor->isSupervisor()) throw new OperationalPermissionException('Cumprimento de requisição permitido somente a supervisor operacional ativo.'); }
}
